using namespace std;

long long getTime(const vector<pair<long long, long long>>& doors) {
    // t 表示到达当前传送门前的最早时刻
    long long t = 0;

    for (int i = 0; i < (int)doors.size(); i++) {
        long long a = doors[i].first;
        long long b = doors[i].second;

        // 当前传送门的完整开关周期
        long long p = a + b;

        // r 表示当前时刻在本周期中的位置
        long long r = t % p;

        // r >= a 时，当前处于关闭阶段
        if (r >= a) {
            // 等待到下一个周期开始，即下一次开启
            t += p - r;
        }

        // 通过当前传送门需要 1 秒
        t++;
    }

    return t;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        vector<pair<long long, long long>> doors(n);

        for (int i = 0; i < n; i++) {
            cin >> doors[i].first >> doors[i].second;
        }

        cout << getTime(doors) << '\n';
    }

    return 0;
}
